        "image": null,
        "transcript": "<b>Question 29:</b> I'm going to pick up the printing order now.<br/>(A) Yes, it was really fun.<br/>(B) Don't forget the receipt.<br/>(C) No, in alphabetical order.",
        "translation": "<b>Câu hỏi 29:</b> Bây giờ tôi đi lấy đơn hàng in ấn đây.<br/><b>(A)</b> Vâng, nó thực sự rất vui.<br/><b>(B)</b> Đừng quên mang theo biên lai nhé.<br/><b>(C)</b> Không, theo thứ tự bảng chữ cái.",
