        "range": "80-82",
        "type": "News report (Bản tin)",
        "audio": "media/ets2019_t6/Test 06-Part 4-80-82.mp3",
        "image": null,
        "transcript": "Good evening. Tonight I'll be talking about a new initiative by G.S. Incorporated, a leading <b>manufacturer of mobile phones and electronic accessories</b>. As part of its commitment to sustainability, G.S. Incorporated announced today that it has started to <b>package its products in a more environmentally friendly way</b>. Now they come in boxes made entirely of recycled materials. After a short commercial break, I'll be <b>interviewing a representative</b> from G.S. Incorporated about what inspired these changes.",
        "translation": "Chào buổi tối. Tối nay tôi sẽ nói về một sáng kiến mới của G.S. Incorporated, nhà sản xuất hàng đầu về điện thoại di động và phụ kiện điện tử. Là một phần trong cam kết đối với sự phát triển bền vững, G.S. Incorporated hôm nay thông báo rằng họ đã bắt đầu đóng gói sản phẩm theo cách thân thiện với môi trường hơn. Giờ đây chúng được đựng trong những chiếc hộp làm hoàn toàn từ vật liệu tái chế. Sau giờ nghỉ quảng cáo ngắn, tôi sẽ phỏng vấn một người đại diện từ G.S. Incorporated về điều gì đã truyền cảm hứng cho những thay đổi này.",
        "vocab": [
          "initiative (n): sáng kiến",
          "leading manufacturer (n): nhà sản xuất hàng đầu",
          "electronic accessories (n): phụ kiện điện tử (= electronic devices)",
          "commitment to (n): cam kết đối với",
          "sustainability (n): tính bền vững",
          "package (v): đóng gói",
          "environmentally friendly (n): thân thiện với môi trường",
          "recycled materials (n): vật liệu tái chế",
          "commercial break (n): giờ nghỉ quảng cáo",
          "representative (n): người đại diện",
          "inspire (v): truyền cảm hứng"
        ],
