        "transcript": "Hello, Ms. Olson. I'm calling from <b>Vine Express</b> to let you know that we're holding a package for you. One of our employees tried to deliver the item to your house three times, but you were not home on any of those occasions. Because the parcel needs to be signed for, <b>you'll have to pick it up at our sorting facility</b> at 896 West Pine Drive between 9 a.m. and 5 p.m. <b>If you don't retrieve the package within seven days, it will be returned to the sender.</b> For more information about the item, please feel free to call us at 555-9172. Thank you.",
        "translation": "Xin chào bà Olson. Tôi gọi từ công ty Vine Express để báo cho bà biết chúng tôi đang giữ một kiện hàng cho bà. Một nhân viên của chúng tôi đã cố gắng giao món hàng tới nhà bà ba lần, nhưng bà đều không có nhà vào cả ba lần đó. Bởi vì bưu kiện này cần có chữ ký nhận, bà sẽ phải tự đến lấy tại cơ sở phân loại hàng của chúng tôi ở địa chỉ 896 West Pine Drive từ 9 giờ sáng đến 5 giờ chiều. Nếu bà không đến lấy kiện hàng trong vòng bảy ngày, nó sẽ được trả lại cho người gửi. Để biết thêm thông tin về món hàng, xin cứ tự nhiên gọi cho chúng tôi theo số 555-9172. Xin cảm ơn.",
        "vocab": [
          "hold a package (v): giữ hộ kiện hàng",
          "deliver the item (v): giao món hàng",
          "on any of those occasions (phr): vào bất kỳ lần nào trong số đó",
          "parcel (n): bưu kiện (= package)",
          "be signed for (v): được ký nhận",
          "pick up (v): đến lấy, nhận hàng",
          "sorting facility (n): cơ sở phân loại hàng",
          "retrieve (v): lấy lại, thu hồi",
          "within seven days (n): trong vòng 7 ngày",
          "return to the sender (v): hoàn trả về người gửi",
          "feel free to (n): xin cứ tự nhiên/thoải mái"
        ],
