        "audio": "media/hackers3_t4/Test04_83-85.mp3",
        "image": null,
        "transcript": "As we discussed in our last meeting, <b>the employee who will receive the gift certificate for having the most sales will be announced today</b>. But before I do this, I'd like to <b>congratulate everyone on the sales team</b>. After calculating your sales from last month and comparing them to those from the previous month, we found that they'd all increased. Several of you boosted your sales by more than 50%, <b>but that still wasn't good enough. Our winner actually doubled her monthly sales</b> by signing a service contract with a hotel chain. I'd like to now ask Christine McKesson to come up and accept her reward.",
        "translation": "Như chúng ta đã thảo luận trong cuộc họp trước, nhân viên nhận được phiếu quà tặng nhờ đạt doanh số cao nhất sẽ được công bố vào hôm nay. Nhưng trước khi làm điều đó, tôi muốn chúc mừng tất cả mọi người trong đội ngũ bán hàng. Sau khi tính toán doanh số tháng trước của các bạn và so sánh với tháng trước đó nữa, chúng tôi nhận thấy tất cả đều đã tăng trưởng. Một vài bạn đã đẩy doanh số tăng hơn 50%, nhưng chừng đó vẫn chưa đủ để giành giải nhất. Người chiến thắng của chúng ta thực tế đã tăng gấp đôi doanh số hàng tháng nhờ ký kết một hợp đồng dịch vụ với một chuỗi khách sạn. Bây giờ tôi xin mời cô Christine McKesson bước lên để nhận phần thưởng của mình.",
