        "type": "Radio broadcast (Bản tin kinh doanh)",
        "audio": "media/hackers3_t4/Test04_86-88.mp3",
        "image": null,
        "transcript": "In business news, local firm Digital Solutions has announced plans to release the latest version of its <b>mobile phone application, SpeakVid</b>. The application allows users to record, edit, and share short video messages. <b>It has become hugely popular, resulting in a sharp rise in the developer's stock prices.</b> The upgrade is anticipated among consumers and investors alike. The general public is excited for the application's updated interface, while business analysts predict that the upgrade will expand the firm's market base. SpeakVid has attracted national media coverage already, and experts believe that interest will increase <b>next month when the new version of the application comes out</b>.",
        "translation": "Trong bản tin kinh doanh, công ty địa phương Digital Solutions vừa công bố kế hoạch phát hành phiên bản mới nhất của ứng dụng điện thoại di động SpeakVid. Ứng dụng này cho phép người dùng quay, chỉnh sửa và chia sẻ các đoạn video ngắn. Nó đã trở nên cực kỳ phổ biến, dẫn đến sự tăng vọt giá cổ phiếu của nhà phát triển. Bản nâng cấp này đang được cả người tiêu dùng lẫn giới đầu tư mong đợi. Công chúng nói chung rất hào hứng với giao diện cập nhật của ứng dụng, trong khi các chuyên gia phân tích kinh doanh dự đoán bản nâng cấp sẽ mở rộng tệp khách hàng của công ty. SpeakVid hiện đã thu hút sự chú ý của truyền thông toàn quốc, và các chuyên gia tin rằng sự quan tâm sẽ còn tăng mạnh vào tháng tới khi phiên bản mới của ứng dụng chính thức ra mắt.",
